package com.johnny.hotel;import com.johnny.hotel.businessdate.BusinessDateService;import com.johnny.hotel.financeexpense.*;import com.johnny.hotel.guest.GuestAccess;import com.johnny.hotel.mapper.SysAuditLogMapper;import com.johnny.hotel.pagination.*;import com.johnny.hotel.payment.*;import com.johnny.hotel.repair.RepairOrderMapper;import com.johnny.hotel.workorder.RoomWorkOrderMapper;import org.junit.jupiter.api.*;import org.springframework.security.access.AccessDeniedException;import java.math.*;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class HotelExpenseServiceTest{HotelExpenseMapper db;GuestAccess access;BusinessDateService dates;PaymentCoreMapper tx;SysAuditLogMapper audit;HotelExpenseService service;Clock clock=Clock.fixed(Instant.parse("2026-09-23T06:00:00Z"),ZoneOffset.UTC);
 @BeforeEach void init(){db=mock(HotelExpenseMapper.class);access=mock(GuestAccess.class);dates=mock(BusinessDateService.class);tx=mock(PaymentCoreMapper.class);audit=mock(SysAuditLogMapper.class);var p=new PaginationProperties();p.setMaxPageSize(100);p.setBrowseLimit(100);service=new HotelExpenseService(db,access,dates,tx,audit,mock(RoomWorkOrderMapper.class),mock(RepairOrderMapper.class),new PaginationSupport(p),clock);when(audit.insert(any())).thenReturn(1);when(db.action(anyLong(),anyString(),anyString(),anyLong(),nullable(String.class))).thenReturn(1);}
 @Test void selfApprovalIsRejected(){var e=HotelExpense.builder().id(1L).createdBy(9L).status(1).build();when(access.activeRoles(9L)).thenReturn(Set.of("FINANCE"));when(db.lock(1L)).thenReturn(e);assertThrows(RuntimeException.class,()->service.approve(1L,new ExpenseCommands.Action("approve-key-1",null),9L));verify(db,never()).approve(anyLong(),anyLong(),any());}
 @Test void approvedExpensePaysOnceAndCreatesOnlyExternalOut(){var e=HotelExpense.builder().id(2L).createdBy(8L).status(2).amount(new BigDecimal("25.00")).currency("CNY").build();var paid=HotelExpense.builder().id(2L).createdBy(8L).status(3).amount(e.getAmount()).currency("CNY").build();when(access.activeRoles(9L)).thenReturn(Set.of("FINANCE"));when(db.lock(2L)).thenReturn(e,paid);when(dates.postingDate()).thenReturn(LocalDate.of(2026,9,23));when(db.paid(anyLong(),any(),anyLong(),any(),anyString(),nullable(String.class))).thenReturn(1);when(tx.insertTransaction(any())).thenReturn(1);when(db.find(2L)).thenReturn(paid);var cmd=new ExpenseCommands.Pay("payment-key-1","bank_transfer","receipt-1");assertEquals(3,service.pay(2L,cmd,9L).getStatus());assertEquals(3,service.pay(2L,cmd,9L).getStatus());var capture=org.mockito.ArgumentCaptor.forClass(HotelTransactionRecord.class);verify(tx,times(1)).insertTransaction(capture.capture());assertEquals("EXTERNAL_OUT",capture.getValue().getDirection());assertEquals("EXPENSE",capture.getValue().getSourceType());verify(dates,times(1)).postingDate();}
 @Test void managerCanOnlyRequestLimitedCategories(){when(access.activeRoles(3L)).thenReturn(Set.of("MANAGER"));var payroll=new ExpenseCommands.Create(new BigDecimal("10.00"),"CNY",ExpenseCategory.PAYROLL,"salary",null,LocalDate.now(clock),null,null,null,4L,"expense-key-1");assertThrows(AccessDeniedException.class,()->service.create(payroll,3L));}
}
